#!/usr/bin/env python3
import os
import re
import subprocess
import requests
import sys

# Ensure dependencies are installed
def install_dependencies():
    packages = ["requests", "gTTS", "pydub"]
    for package in packages:
        try:
            __import__(package)
        except ImportError:
            print(f"Installing {package}...")
            subprocess.check_call([sys.executable, "-m", "pip", "install", package])

# 1. Fetching Web Content
def fetch_article_content(url):
    """Fetch article content using curl for reliability."""
    print(f"Fetching {url}...")
    try:
        # Use curl to get raw HTML
        result = subprocess.run(
            ["curl", "-s", "-L", url], # Added -L to follow redirects
            capture_output=True,
            text=True,
            check=True
        )
        html = result.stdout

        # Simple HTML stripping as per skill
        text = re.sub(r'<script[^>]*>.*?</script>', '', html, flags=re.DOTALL)
        text = re.sub(r'<style[^>]*>.*?</style>', '', html, flags=re.DOTALL)

        # Remove HTML tags
        text = re.sub(r'<[^>]+>', ' ', text)
        text = re.sub(r'\s+', ' ', text).strip()

        # Decode HTML entities
        import html as html_lib
        text = html_lib.unescape(text)

        return text
    except subprocess.CalledProcessError as e:
        print(f"Error fetching {url}: {e}")
        return ""

def verify_content(text, expected_min_chars=1000):
    if len(text) < expected_min_chars:
        print(f"WARNING: Content may be truncated ({len(text)} chars)")
        return False
    return True

# 2. Text Processing
def clean_text_for_tts(text):
    """Clean text for better TTS output."""
    # Remove URLs
    text = re.sub(r'http[s]?://\S+', '', text)
    # Remove footnote markers like [1]
    text = re.sub(r'\[\d+\]', '', text)
    # Normalize whitespace
    text = re.sub(r'\s+', ' ', text)
    # Remove special characters that confuse TTS (keep basic punctuation)
    text = re.sub(r'[^\w\s.,!?;:\'"()-]', '', text)
    return text.strip()

def chunk_text(text, max_chars=4000):
    """Split text into chunks at sentence boundaries."""
    sentences = re.split(r'(?<=[.!?])\s+', text)
    chunks = []
    current_chunk = ""
    for sentence in sentences:
        if len(current_chunk) + len(sentence) < max_chars:
            current_chunk += sentence + " "
        else:
            if current_chunk:
                chunks.append(current_chunk.strip())
            current_chunk = sentence + " "
    if current_chunk:
        chunks.append(current_chunk.strip())
    return chunks

# 3. TTS Conversion
def create_with_elevenlabs(text, output_path):
    print("Generating audio with ElevenLabs...")
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    if not api_key:
        print("ElevenLabs API key missing.")
        return False

    voice_id = "21m00Tcm4TlvDq8ikWAM" # Rachel
    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_el_{i:03d}.mp3"
        print(f"Processing chunk {i+1}/{len(chunks)}...")
        try:
            response = requests.post(
                f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
                headers={
                    "xi-api-key": api_key,
                    "Content-Type": "application/json"
                },
                json={
                    "text": chunk,
                    "model_id": "eleven_turbo_v2_5",
                    "voice_settings": {"stability": 0.5, "similarity_boost": 0.75}
                }
            )
            if response.status_code == 200:
                with open(chunk_file, "wb") as f:
                    f.write(response.content)
                audio_files.append(chunk_file)
            else:
                print(f"ElevenLabs Error: {response.status_code} - {response.text}")
                return False
        except Exception as e:
            print(f"ElevenLabs Exception: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_openai(text, output_path):
    print("Generating audio with OpenAI...")
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        print("OpenAI API key missing.")
        return False

    chunks = chunk_text(text, max_chars=4000)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_oa_{i:03d}.mp3"
        print(f"Processing chunk {i+1}/{len(chunks)}...")
        try:
            response = requests.post(
                "https://api.openai.com/v1/audio/speech",
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type": "application/json"
                },
                json={
                    "model": "tts-1",
                    "input": chunk,
                    "voice": "onyx",
                    "response_format": "mp3"
                }
            )
            if response.status_code == 200:
                with open(chunk_file, "wb") as f:
                    f.write(response.content)
                audio_files.append(chunk_file)
            else:
                print(f"OpenAI Error: {response.status_code} - {response.text}")
                return False
        except Exception as e:
            print(f"OpenAI Exception: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_gtts(text, output_path):
    print("Generating audio with gTTS...")
    try:
        from gtts import gTTS
        chunks = chunk_text(text, max_chars=4500)
        audio_files = []
        for i, chunk in enumerate(chunks):
            chunk_file = f"/tmp/chunk_gtts_{i:03d}.mp3"
            print(f"Processing chunk {i+1}/{len(chunks)}...")
            tts = gTTS(text=chunk, lang='en', slow=False)
            tts.save(chunk_file)
            audio_files.append(chunk_file)
        return concatenate_audio(audio_files, output_path)
    except Exception as e:
        print(f"gTTS Error: {e}")
        return False

def concatenate_audio(audio_files, output_path):
    if not audio_files:
        return False

    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    print(f"Concatenating {len(audio_files)} files to {output_path}...")
    try:
        subprocess.run([
            "ffmpeg", "-y", "-f", "concat", "-safe", "0",
            "-i", list_file, "-c", "copy", output_path
        ], capture_output=True, check=True)

        # Cleanup
        for f in audio_files:
            if os.path.exists(f): os.unlink(f)
        os.unlink(list_file)
        return True
    except subprocess.CalledProcessError as e:
        print(f"FFmpeg Error: {e}")
        return False

def create_audiobook(text, output_path):
    # Check for keys
    has_elevenlabs = bool(os.environ.get("ELEVENLABS_API_KEY"))
    has_openai = bool(os.environ.get("OPENAI_API_KEY"))

    if has_elevenlabs:
        if create_with_elevenlabs(text, output_path): return True
        print("ElevenLabs failed, trying next...")

    if has_openai:
        if create_with_openai(text, output_path): return True
        print("OpenAI failed, trying next...")

    return create_with_gtts(text, output_path)

def main():
    install_dependencies()

    urls = [
        "http://paulgraham.com/ds.html",
        "https://paulgraham.com/foundermode.html"
    ]

    all_text = ""
    for url in urls:
        raw_text = fetch_article_content(url)
        if verify_content(raw_text):
            all_text += f"\n\nTitle: {url.split('/')[-1]}\n\n" + raw_text
        else:
            print(f"Skipping {url} due to verification failure.")

    cleaned_text = clean_text_for_tts(all_text)
    print(f"Total characters to process: {len(cleaned_text)}")

    if len(cleaned_text) < 100:
        print("Not enough text to generate audiobook.")
        return

    if create_audiobook(cleaned_text, "/root/audiobook.mp3"):
        print("Audiobook created successfully at /root/audiobook.mp3")
    else:
        print("Failed to create audiobook.")

